"use strict";(self.webpackChunk_inversifyjs_framework_docs_site=self.webpackChunk_inversifyjs_framework_docs_site||[]).push([["4984"],{1967(e){e.exports=JSON.parse('{"version":{"pluginId":"grpc","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"grpcSidebar":[{"type":"category","label":"Introduction","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/framework/grpc/introduction/getting-started","label":"Getting started","docId":"introduction/getting-started","unlisted":false}]},{"type":"category","label":"Fundamentals","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/framework/grpc/fundamentals/service","label":"Service","docId":"fundamentals/service","unlisted":false},{"type":"link","href":"/framework/grpc/fundamentals/rpc","label":"RPC","docId":"fundamentals/rpc","unlisted":false},{"type":"link","href":"/framework/grpc/fundamentals/parameters","label":"Parameters","docId":"fundamentals/parameters","unlisted":false},{"type":"link","href":"/framework/grpc/fundamentals/middleware","label":"Middleware","docId":"fundamentals/middleware","unlisted":false},{"type":"link","href":"/framework/grpc/fundamentals/guard","label":"Guard","docId":"fundamentals/guard","unlisted":false},{"type":"link","href":"/framework/grpc/fundamentals/interceptor","label":"Interceptor","docId":"fundamentals/interceptor","unlisted":false},{"type":"link","href":"/framework/grpc/fundamentals/pipe","label":"Pipe","docId":"fundamentals/pipe","unlisted":false},{"type":"link","href":"/framework/grpc/fundamentals/error","label":"Error","docId":"fundamentals/error","unlisted":false},{"type":"link","href":"/framework/grpc/fundamentals/error-filter","label":"Error filter","docId":"fundamentals/error-filter","unlisted":false}]},{"type":"category","label":"API","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/framework/grpc/api/inversify-grpc-js-adapter","label":"InversifyGrpcJsAdapter","docId":"api/inversify-grpc-js-adapter","unlisted":false},{"type":"link","href":"/framework/grpc/api/decorators","label":"Decorators","docId":"api/decorators","unlisted":false}],"href":"/framework/grpc/category/api"}]},"docs":{"api/decorators":{"id":"api/decorators","title":"Decorators","description":"Import service and parameter decorators from @inversifyjs/grpc-core. The same package re-exports the shared framework decorators.","sidebar":"grpcSidebar"},"api/inversify-grpc-js-adapter":{"id":"api/inversify-grpc-js-adapter","title":"InversifyGrpcJsAdapter","description":"InversifyGrpcJsAdapter connects an Inversify container to a @grpc/grpc-js Server. Import it from @inversifyjs/grpc-js.","sidebar":"grpcSidebar"},"fundamentals/error":{"id":"fundamentals/error","title":"Error","description":"Throw a GrpcError from a service, guard, middleware, interceptor, or pipe to finish the call with a gRPC status. The adapter sends the error\'s code, details, and optional metadata. This works for unary and streaming RPCs.","sidebar":"grpcSidebar"},"fundamentals/error-filter":{"id":"fundamentals/error-filter","title":"Error filter","description":"Error filters translate an exception into a gRPC status. @CatchError() marks the filter and applies @injectable(). @UseErrorFilter() attaches it to a service or to one RPC. Bind the filter class.","sidebar":"grpcSidebar"},"fundamentals/guard":{"id":"fundamentals/guard","title":"Guard","description":"Guards decide whether an RPC continues. They run after pre-handler middleware and before interceptors and the RPC method.","sidebar":"grpcSidebar"},"fundamentals/interceptor":{"id":"fundamentals/interceptor","title":"Interceptor","description":"Interceptors wrap the RPC method. Code before await next() runs after guards and before the method. Code after await next() runs after the method returns and before post-handler middleware.","sidebar":"grpcSidebar"},"fundamentals/middleware":{"id":"fundamentals/middleware","title":"Middleware","description":"Middleware runs before or after the RPC method. The call is the @grpc/grpc-js server call. For unary and client-streaming RPCs the response argument is the callback. For streaming responses it is the call again. next continues the chain.","sidebar":"grpcSidebar"},"fundamentals/parameters":{"id":"fundamentals/parameters","title":"Parameters","description":"With no parameter decorators, the adapter calls the method the way @grpc/grpc-js calls a raw handler: (call, callback) for unary and client-streaming RPCs, and (call) for server-streaming and bidirectional RPCs.","sidebar":"grpcSidebar"},"fundamentals/pipe":{"id":"fundamentals/pipe","title":"Pipe","description":"Pipes transform a parameter after it is extracted and before the RPC method runs.","sidebar":"grpcSidebar"},"fundamentals/rpc":{"id":"fundamentals/rpc","title":"RPC","description":"@RPC() marks a method as the handler for one RPC name from the service definition.","sidebar":"grpcSidebar"},"fundamentals/service":{"id":"fundamentals/service","title":"Service","description":"A service is a class decorated with @Service(). The decorator records the gRPC service definition and applies @injectable(), so you do not add @injectable() yourself.","sidebar":"grpcSidebar"},"introduction/getting-started":{"id":"introduction/getting-started","title":"Getting started","description":"@inversifyjs/grpc-js builds a @grpc/grpc-js server from classes registered in an Inversify container. Decorators, gRPC status errors, guards, middleware, interceptors, pipes, and error filters come from @inversifyjs/grpc-core.","sidebar":"grpcSidebar"}}}}')}}]);